-- Security Monitoring & Threat Detection 15.0.4
create table if not exists public.podcasting_security_alerts(id uuid primary key default gen_random_uuid(),alert_type text not null,severity text not null check(severity in('low','medium','high','critical')),title text not null,summary text not null,source text not null,subject_key text,details jsonb not null default '{}'::jsonb,dedupe_key text not null,status text not null default 'open' check(status in('open','acknowledged','resolved')),acknowledged_by uuid references auth.users(id) on delete set null,acknowledged_at timestamptz,resolved_by uuid references auth.users(id) on delete set null,resolved_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists podcasting_security_alerts_created_idx on public.podcasting_security_alerts(created_at desc);
create index if not exists podcasting_security_alerts_status_idx on public.podcasting_security_alerts(status,severity,created_at desc);
create unique index if not exists podcasting_security_alerts_open_dedupe_idx on public.podcasting_security_alerts(dedupe_key) where status in('open','acknowledged');
alter table public.podcasting_security_alerts enable row level security;
revoke all on public.podcasting_security_alerts from public,anon,authenticated;
create table if not exists public.podcasting_security_incidents(id uuid primary key default gen_random_uuid(),alert_id uuid references public.podcasting_security_alerts(id) on delete set null,title text not null,severity text not null check(severity in('low','medium','high','critical')),status text not null default 'investigating' check(status in('investigating','contained','resolved','closed')),owner_user_id uuid references auth.users(id) on delete set null,summary text not null default '',investigation_notes text not null default '',resolution text not null default '',created_by uuid not null references auth.users(id),updated_by uuid not null references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),resolved_at timestamptz);
create index if not exists podcasting_security_incidents_updated_idx on public.podcasting_security_incidents(updated_at desc);
alter table public.podcasting_security_incidents enable row level security;
revoke all on public.podcasting_security_incidents from public,anon,authenticated;
create table if not exists public.podcasting_security_notification_outbox(id uuid primary key default gen_random_uuid(),alert_id uuid not null references public.podcasting_security_alerts(id) on delete cascade,recipient_email text not null,status text not null default 'pending' check(status in('pending','sent','failed')),attempts integer not null default 0,provider_message_id text,last_error text,created_at timestamptz not null default now(),sent_at timestamptz,unique(alert_id,recipient_email));
create index if not exists podcasting_security_notification_pending_idx on public.podcasting_security_notification_outbox(status,created_at);
alter table public.podcasting_security_notification_outbox enable row level security;
revoke all on public.podcasting_security_notification_outbox from public,anon,authenticated;
create or replace function private.cr_security_emit_alert(p_type text,p_severity text,p_title text,p_summary text,p_source text,p_subject_key text,p_details jsonb,p_dedupe_key text) returns uuid language plpgsql security definer set search_path='' as $$
declare v_id uuid; begin
 insert into public.podcasting_security_alerts(alert_type,severity,title,summary,source,subject_key,details,dedupe_key) values(p_type,p_severity,p_title,p_summary,p_source,p_subject_key,coalesce(p_details,'{}'::jsonb),p_dedupe_key)
 on conflict(dedupe_key) where status in('open','acknowledged') do update set updated_at=now(),details=excluded.details,summary=excluded.summary returning id into v_id;
 if p_severity in('high','critical') then insert into public.podcasting_security_notification_outbox(alert_id,recipient_email)
 select v_id,u.email from auth.users u where u.email is not null and (lower(coalesce(u.raw_app_meta_data->>'role','')) in('admin','owner','super_admin') or exists(select 1 from public.members m where m.user_id=u.id and lower(coalesce(m.status,''))='active' and lower(coalesce(m.role,'')) in('admin','owner','super_admin')) or exists(select 1 from public.hub_admins h where h.user_id=u.id and lower(coalesce(h.role,'')) in('admin','owner','super_admin')) or exists(select 1 from public.cr_admins a where a.user_id=u.id and a.is_active and lower(coalesce(a.role,'')) in('admin','owner','super_admin'))) on conflict(alert_id,recipient_email) do nothing; end if; return v_id; end $$;
create or replace function private.cr_security_failed_login_alert() returns trigger language plpgsql security definer set search_path='' as $$
declare v_count integer; begin select count(*) into v_count from public.podcasting_auth_failure_events where identifier_hash=new.identifier_hash and attempted_at>now()-interval '15 minutes';
 if v_count>=5 then perform private.cr_security_emit_alert('repeated_failed_logins','high','Repeated failed password sign-ins',v_count||' failed password sign-ins were recorded for one privacy-preserving identifier fingerprint within 15 minutes.','podcasting_auth_failure_events',left(new.identifier_hash,16),jsonb_build_object('failure_count',v_count,'window_minutes',15,'identifier_fingerprint',left(new.identifier_hash,16)),'failed-login:'||left(new.identifier_hash,32)); end if; return new; end $$;
drop trigger if exists podcasting_security_failed_login_alert on public.podcasting_auth_failure_events;
create trigger podcasting_security_failed_login_alert after insert on public.podcasting_auth_failure_events for each row execute function private.cr_security_failed_login_alert();
create or replace function private.cr_security_admin_activity_alert() returns trigger language plpgsql security definer set search_path='' as $$
declare v_count integer; begin select count(*) into v_count from public.cr_podcast_admin_audit where admin_user_id=new.admin_user_id and created_at>now()-interval '10 minutes';
 if v_count>=15 then perform private.cr_security_emit_alert('unusual_admin_activity','high','Unusually high administrator activity',v_count||' administrator audit events were recorded for one administrator within 10 minutes.','cr_podcast_admin_audit',new.admin_user_id::text,jsonb_build_object('event_count',v_count,'window_minutes',10,'admin_user_id',new.admin_user_id),'admin-activity:'||new.admin_user_id::text||':'||date_trunc('hour',now())::text); end if; return new; end $$;
drop trigger if exists podcasting_security_admin_activity_alert on public.cr_podcast_admin_audit;
create trigger podcasting_security_admin_activity_alert after insert on public.cr_podcast_admin_audit for each row execute function private.cr_security_admin_activity_alert();
create or replace function public.podcasting_security_monitor_scan() returns jsonb language plpgsql security definer set search_path='' as $$
declare v_row record; v_alerts integer; v_critical integer; begin
 if auth.uid() is null or not coalesce(private.crowrules_is_admin_impl(),false) then raise exception 'ADMIN_AUTH_REQUIRED' using errcode='42501'; end if;
 for v_row in select user_id,count(*) session_count from auth.sessions group by user_id having count(*)>=8 loop perform private.cr_security_emit_alert('session_anomaly','medium','Unusually high active session count',v_row.session_count||' active sessions are associated with one account. Confirm whether these sessions are expected.','auth.sessions',v_row.user_id::text,jsonb_build_object('session_count',v_row.session_count,'user_id',v_row.user_id),'session-anomaly:'||v_row.user_id::text||':'||date_trunc('hour',now())::text); end loop;
 for v_row in select identifier_hash,count(*) failure_count from public.podcasting_auth_failure_events where attempted_at>now()-interval '15 minutes' group by identifier_hash having count(*)>=5 loop perform private.cr_security_emit_alert('repeated_failed_logins','high','Repeated failed password sign-ins',v_row.failure_count||' failed password sign-ins were recorded for one identifier fingerprint in 15 minutes.','podcasting_auth_failure_events',left(v_row.identifier_hash,16),jsonb_build_object('failure_count',v_row.failure_count,'identifier_fingerprint',left(v_row.identifier_hash,16)),'failed-login-scan:'||left(v_row.identifier_hash,32)); end loop;
 select count(*) into v_alerts from public.podcasting_security_alerts where status in('open','acknowledged'); select count(*) into v_critical from public.podcasting_security_alerts where severity='critical' and status in('open','acknowledged'); return jsonb_build_object('open_alerts',v_alerts,'critical_alerts',v_critical,'scan_at',now()); end $$;
create or replace function public.podcasting_security_alerts_list(p_status text default 'all',p_limit integer default 100) returns table(id uuid,alert_type text,severity text,title text,summary text,source text,subject_key text,details jsonb,status text,acknowledged_by uuid,acknowledged_at timestamptz,created_at timestamptz,updated_at timestamptz) language plpgsql security definer set search_path='' as $$
begin if auth.uid() is null or not coalesce(private.crowrules_is_admin_impl(),false) then raise exception 'ADMIN_AUTH_REQUIRED' using errcode='42501'; end if; return query select a.id,a.alert_type,a.severity,a.title,a.summary,a.source,a.subject_key,a.details,a.status,a.acknowledged_by,a.acknowledged_at,a.created_at,a.updated_at from public.podcasting_security_alerts a where p_status='all' or a.status=p_status order by case a.severity when 'critical' then 1 when 'high' then 2 when 'medium' then 3 else 4 end,a.created_at desc limit greatest(1,least(coalesce(p_limit,100),250)); end $$;
create or replace function public.podcasting_security_alert_ack(p_alert_id uuid,p_action text default 'acknowledge') returns jsonb language plpgsql security definer set search_path='' as $$
declare v_status text; begin if auth.uid() is null or not coalesce(private.crowrules_is_admin_impl(),false) then raise exception 'ADMIN_AUTH_REQUIRED' using errcode='42501'; end if; if p_action not in('acknowledge','resolve') then raise exception 'INVALID_ALERT_ACTION'; end if;
 update public.podcasting_security_alerts set status=case when p_action='resolve' then 'resolved' else 'acknowledged' end,acknowledged_by=case when p_action='acknowledge' then auth.uid() else acknowledged_by end,acknowledged_at=case when p_action='acknowledge' then now() else acknowledged_at end,resolved_by=case when p_action='resolve' then auth.uid() else resolved_by end,resolved_at=case when p_action='resolve' then now() else resolved_at end,updated_at=now() where id=p_alert_id returning status into v_status;
 if v_status is null then raise exception 'ALERT_NOT_FOUND' using errcode='P0002'; end if; insert into public.cr_podcast_admin_audit(admin_user_id,action,entity_type,entity_id,details) values(auth.uid(),'security.alert_'||p_action,'podcasting_security_alerts',p_alert_id,jsonb_build_object('status',v_status)); return jsonb_build_object('alert_id',p_alert_id,'status',v_status); end $$;
create or replace function public.podcasting_security_incidents_list(p_limit integer default 100) returns table(id uuid,alert_id uuid,title text,severity text,status text,owner_user_id uuid,summary text,investigation_notes text,resolution text,created_by uuid,updated_by uuid,created_at timestamptz,updated_at timestamptz,resolved_at timestamptz) language plpgsql security definer set search_path='' as $$
begin if auth.uid() is null or not coalesce(private.crowrules_is_admin_impl(),false) then raise exception 'ADMIN_AUTH_REQUIRED' using errcode='42501'; end if; return query select i.id,i.alert_id,i.title,i.severity,i.status,i.owner_user_id,i.summary,i.investigation_notes,i.resolution,i.created_by,i.updated_by,i.created_at,i.updated_at,i.resolved_at from public.podcasting_security_incidents i order by i.updated_at desc limit greatest(1,least(coalesce(p_limit,100),250)); end $$;
create or replace function public.podcasting_security_incident_save(p_id uuid,p_alert_id uuid,p_title text,p_severity text,p_status text,p_owner_user_id uuid,p_summary text,p_notes text,p_resolution text) returns jsonb language plpgsql security definer set search_path='' as $$
declare v_id uuid; begin if auth.uid() is null or not coalesce(private.crowrules_is_admin_impl(),false) then raise exception 'ADMIN_AUTH_REQUIRED' using errcode='42501'; end if; if length(trim(coalesce(p_title,'')))<3 or length(p_title)>180 then raise exception 'INVALID_INCIDENT_TITLE'; end if; if p_severity not in('low','medium','high','critical') or p_status not in('investigating','contained','resolved','closed') then raise exception 'INVALID_INCIDENT_STATE'; end if;
 if p_id is null then insert into public.podcasting_security_incidents(alert_id,title,severity,status,owner_user_id,summary,investigation_notes,resolution,created_by,updated_by,resolved_at) values(p_alert_id,trim(p_title),p_severity,p_status,p_owner_user_id,left(coalesce(p_summary,''),2000),left(coalesce(p_notes,''),12000),left(coalesce(p_resolution,''),4000),auth.uid(),auth.uid(),case when p_status in('resolved','closed') then now() end) returning id into v_id;
 else update public.podcasting_security_incidents set alert_id=p_alert_id,title=trim(p_title),severity=p_severity,status=p_status,owner_user_id=p_owner_user_id,summary=left(coalesce(p_summary,''),2000),investigation_notes=left(coalesce(p_notes,''),12000),resolution=left(coalesce(p_resolution,''),4000),updated_by=auth.uid(),updated_at=now(),resolved_at=case when p_status in('resolved','closed') then coalesce(resolved_at,now()) else null end where id=p_id returning id into v_id; if v_id is null then raise exception 'INCIDENT_NOT_FOUND' using errcode='P0002'; end if; end if;
 insert into public.cr_podcast_admin_audit(admin_user_id,action,entity_type,entity_id,details) values(auth.uid(),case when p_id is null then 'security.incident_created' else 'security.incident_updated' end,'podcasting_security_incidents',v_id,jsonb_build_object('severity',p_severity,'status',p_status)); return jsonb_build_object('incident_id',v_id,'status',p_status); end $$;
create or replace function public.podcasting_security_trends(p_days integer default 14) returns jsonb language plpgsql security definer set search_path='' as $$
declare v_result jsonb; v_days integer:=greatest(1,least(coalesce(p_days,14),90)); begin if auth.uid() is null or not coalesce(private.crowrules_is_admin_impl(),false) then raise exception 'ADMIN_AUTH_REQUIRED' using errcode='42501'; end if;
 select jsonb_build_object('days',v_days,'alerts_by_day',coalesce((select jsonb_agg(jsonb_build_object('date',q.bucket_date,'total',q.total,'critical',q.critical,'high',q.high) order by q.bucket_date) from (select date_trunc('day',created_at)::date bucket_date,count(*) total,count(*) filter(where severity='critical') critical,count(*) filter(where severity='high') high from public.podcasting_security_alerts where created_at>=now()-make_interval(days=>v_days) group by 1) q),'[]'::jsonb),'by_type',coalesce((select jsonb_agg(jsonb_build_object('type',q.alert_type,'count',q.n) order by q.n desc) from (select alert_type,count(*) n from public.podcasting_security_alerts where created_at>=now()-make_interval(days=>v_days) group by alert_type) q),'[]'::jsonb),'open_alerts',(select count(*) from public.podcasting_security_alerts where status in('open','acknowledged')),'unacknowledged',(select count(*) from public.podcasting_security_alerts where status='open'),'incidents_open',(select count(*) from public.podcasting_security_incidents where status in('investigating','contained')),'notification_pending',(select count(*) from public.podcasting_security_notification_outbox where status='pending')) into v_result; return v_result; end $$;
revoke all on function public.podcasting_security_monitor_scan() from public,anon;
revoke all on function public.podcasting_security_alerts_list(text,integer) from public,anon;
revoke all on function public.podcasting_security_alert_ack(uuid,text) from public,anon;
revoke all on function public.podcasting_security_incidents_list(integer) from public,anon;
revoke all on function public.podcasting_security_incident_save(uuid,uuid,text,text,text,uuid,text,text,text) from public,anon;
revoke all on function public.podcasting_security_trends(integer) from public,anon;
grant execute on function public.podcasting_security_monitor_scan() to authenticated;
grant execute on function public.podcasting_security_alerts_list(text,integer) to authenticated;
grant execute on function public.podcasting_security_alert_ack(uuid,text) to authenticated;
grant execute on function public.podcasting_security_incidents_list(integer) to authenticated;
grant execute on function public.podcasting_security_incident_save(uuid,uuid,text,text,text,uuid,text,text,text) to authenticated;
grant execute on function public.podcasting_security_trends(integer) to authenticated;
